children:
/* Home final hero copy lock v1 */
@media (min-width: 992px) {
  html body.body.crays-mirror.route-home header.section_header5 div.header-text-wrapper > p.text-size-medium.text-color-white.header {
    width: 560px !important;
    max-width: 560px !important;
  }
}

/* Home hero card microcopy final lock v1 */
@media (min-width: 992px) {
  html body.body.crays-mirror.route-home header.section_header5 div.wrapper-blurry-cards > div.wrapper-card div.wrapper-text-box-card > div.text-size-small.text-color-muted {
    font-size: 15.6px !important;
    line-height: 21px !important;
    white-space: nowrap !important;
  }
}

/* Home project feature stack: Mercedes Island plus Coffee v1 */
html body.body.crays-mirror.route-home .crays-home-project-feature-stack {
  grid-column: 1 / -1 !important;
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) !important;
  grid-auto-rows: 1fr !important;
  gap: 18px !important;
}

html body.body.crays-mirror.route-home .crays-home-project-feature-stack .crays-home-project-card--feature {
  grid-column: 1 / -1 !important;
  display: grid !important;
  grid-template-columns: minmax(0, 0.66fr) minmax(430px, 0.54fr) !important;
  min-height: 0 !important;
  background:
    linear-gradient(90deg, rgba(3, 7, 12, 0.88) 0%, rgba(7, 27, 42, 0.86) 46%, rgba(19, 42, 98, 0.76) 100%),
    #06131d !important;
}

html body.body.crays-mirror.route-home .crays-home-project-feature-stack .crays-home-project-card--feature :is(h3, strong, .crays-home-button--text) {
  color: #ffffff !important;
}

html body.body.crays-mirror.route-home .crays-home-project-feature-stack .crays-home-project-card--feature .crays-home-project-card__copy {
  color: rgba(255, 255, 255, 0.76) !important;
}

html body.body.crays-mirror.route-home .crays-home-project-feature-stack .crays-home-project-card--feature .crays-home-project-card__image {
  aspect-ratio: auto !important;
  min-height: 0 !important;
  overflow: hidden !important;
}

html body.body.crays-mirror.route-home .crays-home-project-feature-stack .crays-home-project-card--feature .crays-home-project-card__image img {
  width: 100% !important;
  height: 100% !important;
  min-height: 0 !important;
  object-fit: cover !important;
  object-position: center center !important;
}

html body.body.crays-mirror.route-home .crays-home-project-feature-stack .crays-home-project-card--feature .crays-home-project-card__body {
  min-height: 100% !important;
  display: flex !important;
  flex-direction: column !important;
  justify-content: flex-start !important;
  padding: clamp(20px, 1.85vw, 26px) !important;
}

html body.body.crays-mirror.route-home .crays-home-project-feature-stack .crays-home-project-card--feature h3 {
  max-width: 20ch !important;
  font-size: clamp(23px, 1.75vw, 30px) !important;
  line-height: 1.01 !important;
}

html body.body.crays-mirror.route-home .crays-home-project-feature-stack .crays-home-project-card--feature .crays-home-project-card__copy {
  max-width: 58ch !important;
  font-size: clamp(15px, 0.94vw, 16.2px) !important;
  line-height: 1.48 !important;
}

html body.body.crays-mirror.route-home .crays-home-project-feature-stack .crays-home-project-card--feature .crays-home-button--text {
  align-self: flex-start !important;
  margin-top: auto !important;
  padding-top: 0 !important;
}

@media (max-width: 1180px) {
  html body.body.crays-mirror.route-home .crays-home-project-feature-stack .crays-home-project-card--feature {
    display: grid !important;
    grid-template-columns: minmax(0, 1fr) !important;
    grid-auto-rows: auto !important;
  }

  html body.body.crays-mirror.route-home .crays-home-project-feature-stack {
    grid-auto-rows: auto !important;
  }

  html body.body.crays-mirror.route-home .crays-home-project-feature-stack .crays-home-project-card--feature .crays-home-project-card__image {
    aspect-ratio: 16 / 9 !important;
    min-height: 0 !important;
  }
}

